using InventoryTracker.Api.Auth;

namespace InventoryTracker.Api.Domain;

/// <summary>
/// A request for extra material for an order that is InProduction (US-16 to US-18, decision #4).
/// Table <c>ComplementaryOrders</c>.
/// </summary>
/// <remarks>
/// It has its own number sequence, used as the primary key (design 2.1). AC-05.3: every status change records a
/// time and a user, which also gives the status history. Complementary orders are never deleted.
/// </remarks>
public class ComplementaryOrder
{
    /// <summary>The complementary order number and primary key, generated by the database.</summary>
    public int Number { get; set; }

    /// <summary>Foreign key to the production order the extra material is for.</summary>
    public int ParentOrderNumber { get; set; }

    /// <summary>The parent order, when loaded.</summary>
    public ProductionOrder ParentOrder { get; set; } = null!;

    /// <summary>Current status. Stored as the enum name.</summary>
    public ComplementaryOrderStatus Status { get; set; }

    /// <summary>US-16: why extra material is needed; required, up to 500 characters.</summary>
    public string Reason { get; set; } = string.Empty;

    /// <summary>AC-05.3: when the request was made (UTC).</summary>
    public DateTime RequestedAt { get; set; }

    /// <summary>AC-05.3: foreign key to the user who made the request.</summary>
    public string RequestedById { get; set; } = string.Empty;

    /// <summary>The requester, when loaded.</summary>
    public AppUser RequestedBy { get; set; } = null!;

    /// <summary>AC-05.3: when a Manager approved it.</summary>
    public DateTime? ApprovedAt { get; set; }

    /// <summary>AC-05.3: foreign key to the Manager who approved it.</summary>
    public string? ApprovedById { get; set; }

    /// <summary>The approver, when loaded.</summary>
    public AppUser? ApprovedBy { get; set; }

    /// <summary>AC-05.3: when a Manager rejected it.</summary>
    public DateTime? RejectedAt { get; set; }

    /// <summary>AC-05.3: foreign key to the Manager who rejected it.</summary>
    public string? RejectedById { get; set; }

    /// <summary>The Manager who rejected it, when loaded.</summary>
    public AppUser? RejectedBy { get; set; }

    /// <summary>Optional note given with a rejection (US-17), up to 500 characters.</summary>
    public string? DecisionNote { get; set; }

    /// <summary>AC-05.3: when the material was sent.</summary>
    public DateTime? SentAt { get; set; }

    /// <summary>AC-05.3: foreign key to the user who sent the material.</summary>
    public string? SentById { get; set; }

    /// <summary>The sender, when loaded.</summary>
    public AppUser? SentBy { get; set; }

    /// <summary>AC-05.3: when it was cancelled automatically (AC-19.6, AC-21.4).</summary>
    public DateTime? CancelledAt { get; set; }

    /// <summary>The user who completed or cancelled the parent order, which caused the automatic cancellation.</summary>
    public string? CancelledById { get; set; }

    /// <summary>That user, when loaded.</summary>
    public AppUser? CancelledBy { get; set; }

    /// <summary>"Parent order completed" or "Parent order cancelled"; up to 100 characters.</summary>
    public string? CancellationNote { get; set; }

    /// <summary>The materials requested; each must already be on the parent order.</summary>
    public List<ComplementaryOrderLine> Lines { get; set; } = [];
}
